    return int(readLn())

def readStrings():
    return readLn().split(" ")

def readInts():
    return list(map(int, readStrings()))

def main():
    n, MOD = readInts()

    def add(x, y):
        s = x + y
        return s if s < MOD else s - MOD

    def sub(x, y):
        return x - y + MOD if x < y else x - y

    DP = [ [] for _ in range(n + 1) ]
    DP[0] = [1]

    for i in range(1, n + 1):
        dim = i * (i - 1) // 2
        DP[i] = [0] * (dim + 1)
        s = 0
        for j in range(dim + 1):
            if j < len(DP[i - 1]):
                s = add(s, DP[i - 1][j])
            DP[i][j] = s
            if j >= i - 1:
                s = sub(s, DP[i - 1][j - i + 1])

    pf = [0] * (n * n)
    ans = 0

    for cut in range(2, n):
        dim = cut * (cut - 1) // 2
        for i in range(1, dim + 1):
            pf[i] = add(pf[i - 1], DP[cut][i])

        def range_sum(l, r):
            if l > min(r, dim):
                return 0
            return sub(pf[min(r, dim)], pf[l - 1] if l > 0 else 0)

