        aux = 0
        s = 0
        for x in range(dim, -1, -1):
            yo = (range_sum(x + cut + 1, dim) * (cut * (cut + 1) // 2) + s) % MOD
            tot = add(tot, (DP[cut][x] * yo) % MOD)
            if x + cut <= dim:
                s = sub(s, DP[cut][x + cut] * (cut * (cut + 1) // 2 - 1) % MOD)
